messages.content:
Game edukasi "Daur Ulang Dash": pemain melompat menghindari rintangan sambil mengambil item sesuai kategori target (Dapat vs Tidak Dapat Didaur Ulang). Asumsi: item salah menampilkan penjelasan singkat, dan miskonsepsi "semua plastik bisa didaur ulang" diuji lewat item sedotan plastik.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "daur-ulang-dash", title: "Daur Ulang Dash", seed: "daur-ulang-01",
  theme: { preset: "cartoon" },

  learning: {
    subject: "Lingkungan Hidup",
    concept: "Membedakan bahan yang dapat dan tidak dapat didaur ulang",
    objectives: ["Mengelompokkan benda berdasarkan kemampuan didaur ulang"],
    misconceptions: ["Semua jenis plastik bisa didaur ulang"],
    mode: "category",
    categories: [
      { id: "dapat",   label: "Dapat Didaur Ulang",     color: "#3FA34D" },
      { id: "tidak",   label: "Tidak Dapat Didaur Ulang", color: "#E5484D" }
    ],
    items: [
      { id: "botol-pet",     label: "Botol plastik PET",       category: "dapat", explain: "Plastik PET mudah dilebur ulang menjadi bahan baru." },
      { id: "kaleng",        label: "Kaleng aluminium",        category: "dapat", explain: "Logam aluminium bisa didaur ulang berulang kali." },
      { id: "koran",         label: "Koran bekas",             category: "dapat", explain: "Serat kertas bisa diolah kembali menjadi kertas baru." },
      { id: "botol-kaca",    label: "Botol kaca",              category: "dapat", explain: "Kaca dapat dilebur dan dibentuk ulang tanpa batas." },
      { id: "puntung",       label: "Puntung rokok",           category: "tidak", explain: "Residu beracun dan bercampur bahan kimia; tidak didaur ulang." },
      { id: "piring-kertas", label: "Piring kertas bekas",     category: "tidak", explain: "Berminyak dan kotor sehingga sulit diproses ulang." },
      { id: "sedotan",       label: "Sedotan plastik sekali pakai", category: "tidak", explain: "Terlalu kecil dan tipis; tidak semua plastik bisa didaur ulang." },
      { id: "styrofoam",     label: "Styrofoam bekas",         category: "tidak", explain: "Sulit terurai dan sulit didaur ulang." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "tong-sampah", w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "genangan",    w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST

